{
  "missing_information": [
    {
      "category": "Activity Discovery",
      "gap": "No detail on where or how the parent searches for activities (e.g., online directories, provider websites, word of mouth, community boards)",
      "why_it_matters": "The discovery channel determines whether search and filtering steps can be automated or aggregated"
    },
    {
      "category": "Eligibility and Fit Criteria",
      "gap": "The criteria used to decide whether an activity 'fits' are undefined (e.g., age range, cost, location, time slot, skill level)",
      "why_it_matters": "Without knowing the fit criteria, it is impossible to model the decision logic or automate eligibility checks"
    },
    {
      "category": "Enrollment Process",
      "gap": "The enrollment steps are not described (e.g., online form, in-person registration, payment, waitlist handling)",
      "why_it_matters": "Enrollment sub-steps vary widely in automation potential; payment and form submission may be fully automatable while waitlists require monitoring"
    },
    {
      "category": "Calendar Integration",
      "gap": "It is unclear which calendar system is used and how events are added (manual entry, shared family calendar, app integration)",
      "why_it_matters": "Automated calendar updates depend on the system in use and whether an API or integration point exists"
    },
    {
      "category": "Schedule Change Notification",
      "gap": "The mechanism by which the provider communicates schedule changes is not specified (email, app notification, phone call, website update)",
      "why_it_matters": "The notification channel determines whether change detection can be automated and how quickly the parent is informed"
    },
    {
      "category": "Rescheduling Response",
      "gap": "What 'rearranging plans' involves is vague — it is unknown whether this affects only the family calendar, other commitments, transportation, or requires contacting the provider",
      "why_it_matters": "The scope of the rescheduling response defines how many downstream steps exist and which could be automated or assisted"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Where do you typically search for child activities — for example, do you use specific websites, apps, printed brochures, or rely on recommendations — and do you search in one place or across multiple sources?",
      "targets": ["Activity Discovery"]
    },
    {
      "id": "Q2",
      "question": "What are the main criteria you check to decide whether an activity is a good fit for your child, such as age group, schedule timing, location, cost, or skill level?",
      "targets": ["Eligibility and Fit Criteria"]
    },
    {
      "id": "Q3",
      "question": "Can you walk me through the steps you take to actually enroll once you have decided on an activity — for instance, is there an online form, a payment step, or any waitlist situation you have encountered?",
      "targets": ["Enrollment Process"]
    },
    {
      "id": "Q4",
      "question": "How do you add the activity to your calendar — do you enter it manually, use a shared family calendar app, or does any system create the event automatically?",
      "targets": ["Calendar Integration"]
    },
    {
      "id": "Q5",
      "question": "How does the activity provider typically inform you of a schedule change — for example, by email, a push notification from an app, a phone call, or a post on their website?",
      "targets": ["Schedule Change Notification"]
    },
    {
      "id": "Q6",
      "question": "When you rearrange your plans after a schedule change, what does that process involve — is it only updating your calendar, or does it also include coordinating transportation, notifying other family members, or contacting the provider to confirm?",
      "targets": ["Rescheduling Response"]
    }
  ]
}
